/**
 * busy-free.ts —— 忙闲时间计算（纯函数）
 *
 * 核心能力：
 * 1. 从忙时段反推空闲时段
 * 2. 按工作时间过滤（9:00-18:00）
 * 3. 最小时长过滤
 * 4. 多人共同空闲时间
 * 5. 单日负载比例计算
 */
export interface Interval {
    start: Date;
    end: Date;
    summary?: string;
    status?: 'busy' | 'free' | 'tentative';
}
export interface WorkHours {
    startHour: number;
    endHour: number;
}
export interface DateRange {
    start: Date;
    end: Date;
}
/**
 * 给定一组忙碌时段，反推一天内的空闲时段
 * @param busyIntervals 忙碌时段（会被裁剪到工作时间内排序合并）
 * @param workHours 工作时间
 * @param day 哪一天（取年月日部分）
 * @param minDurationMinutes 最少空闲时长（分钟）
 */
export declare function findFreeSlotsForDay(busyIntervals: Interval[], workHours: WorkHours, day: Date, minDurationMinutes?: number): Interval[];
/**
 * 计算日期范围内每天的空闲时段
 */
export declare function findFreeSlots(busyIntervals: Interval[], workHours: WorkHours, dateRange: DateRange, minDurationMinutes?: number): {
    date: string;
    slots: Interval[];
}[];
/**
 * 多人员共同空闲时段：找所有人都有空的时间段
 * 思路：把所有人的忙碌时段合并成一个"集体忙碌"集合，再反推
 */
export declare function findCommonFreeSlots(usersBusy: Record<string, Interval[]>, workHours: WorkHours, dateRange: DateRange, minDurationMinutes?: number): {
    date: string;
    slots: Interval[];
}[];
/**
 * 计算某人某天的负载比例（忙碌分钟 / 工作分钟）
 */
export declare function computeDayLoad(busyIntervals: Interval[], day: Date, workHours: WorkHours): {
    loadRatio: number;
    busyMinutes: number;
    totalWorkMinutes: number;
};
/**
 * 批量计算多天的负载
 */
export declare function computeDayLoads(busyIntervals: Interval[], dateRange: DateRange, workHours: WorkHours): {
    date: string;
    loadRatio: number;
    busyMinutes: number;
    totalWorkMinutes: number;
}[];
